import { computed } from 'vue'
import { useRoute, useFetch } from '#app'
import { useCart } from '~/composables/useCart'
import { useDiscount } from '~/composables/useDiscount'
import { useNotify } from '#layers/base/app/composables/useNotify'
import { applyDiscount } from '~/utils/discount'
import { formatMoney } from '~/utils/money'

const route = useRoute()
const { data: product } = await useFetch<Product & { price: string }>(`/api/products/${route.params.slug}`)
const { add } = useCart()
const { notify } = useNotify()
const { percent } = useDiscount()

/** Price after the active discount code, computed exactly like the cart total. */
const discountedPrice = computed(() => {
  if (!product.value)
    return ''
  return formatMoney(applyDiscount(product.value.priceCents, percent.value))
})
